function ModuloTarifas() {
  const [gds, setGds] = useState("AMADEUS");
  const [cotacao, setCotacao] = useState("");
  const [voo, setVoo] = useState("");
  const [cabine, setCabine] = useState("");
  const [bagagem, setBagagem] = useState("");
  const [multaRem, setMultaRem] = useState("");
  const [multaReemb, setMultaReemb] = useState("");
  const [rav, setRav] = useState("7");
  const [fee, setFee] = useState("0");
  const [parcelas, setParcelas] = useState("10x sem juros");
  const [markup, setMarkup] = useState(false);
  const [markupPct, setMarkupPct] = useState("10");
  const [resultado, setResultado] = useState(null);
  const [copied, setCopied] = useState(false);

  const parseCotacao = (text, gdsType) => {
    const raw = text.toUpperCase();
    let tUSD=0,tBRL=0,totalBRL=0,exchangeRate=0,fareFamily="";
    if(gdsType==="AMADEUS"){
      const usdM=raw.match(/^USD\s+([\d,\.]+)/m);
      tUSD=usdM?parseFloat(usdM[1].replace(",",".")):0;
      if(!tUSD){const usdAny=raw.match(/\bUSD\s+([\d,\.]+)/);tUSD=usdAny?parseFloat(usdAny[1].replace(",",".")):0;}
      if(!tUSD){const nucM=raw.match(/NUC\s*([\d,\.]+)/i);tUSD=nucM?parseFloat(nucM[1].replace(",",".")):0;}
      const allBrlLines=[...raw.matchAll(/^BRL\s+([\d,\.]+)(.*)/gm)];
      const totalLines=allBrlLines.filter(m=>m[2].trim()==="");
      if(totalLines.length>0)totalBRL=parseFloat(totalLines[totalLines.length-1][1].replace(",","."));
      const tarifaLine=allBrlLines.find(m=>m[2].trim()!==""&&!m[2].trim().startsWith("-"));
      if(tarifaLine)tBRL=parseFloat(tarifaLine[1].replace(",","."));
      if(!tBRL&&totalBRL>0&&tUSD>0){
        const rateM2=raw.match(/RATE\s+USED\s+1\s*USD\s*[=:]\s*([\d,\.]+)\s*BRL/i);
        const rate2=rateM2?parseFloat(rateM2[1].replace(",",".")):0;
        if(rate2>0)tBRL=tUSD*rate2;
      }
      const rateM=raw.match(/RATE\s+USED\s+1\s*USD\s*[=:]\s*([\d,\.]+)\s*BRL/i);
      if(rateM)exchangeRate=parseFloat(rateM[1].replace(",","."));
      if(!exchangeRate&&tUSD>0&&tBRL>0)exchangeRate=tBRL/tUSD;
      const famM=raw.match(/FARE\s+FAMILY\s*:\s*\w+\s*:\s*[\d\-]+\s*:\s*(\w+)/i);
      if(famM)fareFamily=famM[1];
    } else if(gdsType==="GALILEO"){
      const galM=raw.match(/FQG\s*\d+\s+BRL\s+([\d\.]+)\s+([\d\.]+)\s+([\d\.]+)/i);
      if(galM){tBRL=parseFloat(galM[1]);totalBRL=parseFloat(galM[3]);}
      const bsrM=raw.match(/BSR\s*1USD\s*[-=]\s*([\d\.]+)/i);
      if(bsrM&&tBRL>0){exchangeRate=parseFloat(bsrM[1]);tUSD=tBRL/exchangeRate;}
    } else if(gdsType==="SABRE"){
      const usdM=raw.match(/USD\s*([\d\.]+)/i);tUSD=usdM?parseFloat(usdM[1]):0;
      const brlM=raw.match(/BRL\s*([\d\.]+)/i);tBRL=brlM?parseFloat(brlM[1]):0;
      const totM=raw.match(/BRL\s*([\d\.]+)\s+ADT/i);totalBRL=totM?parseFloat(totM[1]):0;
      if(!totalBRL)totalBRL=tBRL;
      if(tUSD>0&&tBRL>0)exchangeRate=tBRL/tUSD;
    }
    if(!totalBRL&&tBRL>0)totalBRL=tBRL;
    const taxesBRL=totalBRL>tBRL?totalBRL-tBRL:0;
    return{tUSD,tBRL,totalBRL,taxesBRL,exchangeRate,fareFamily};
  };

  const calcular=()=>{
    const p=parseCotacao(cotacao,gds);
    if(!p.tUSD&&!p.totalBRL)return;
    let tUSD=p.tUSD,tBRL=p.tBRL,totalBRL=p.totalBRL;
    let tUSDOriginal=tUSD,tBRLOriginal=tBRL,totalBRLOriginal=totalBRL;
    let comMarkup=false;
    if(markup&&parseFloat(markupPct)>0){
      const mp=parseFloat(markupPct)/100;
      tUSD=tUSD/(1-mp);
      const rate=p.exchangeRate||(tBRLOriginal/tUSDOriginal)||1;
      tBRL=tUSD*rate;
      const taxas=totalBRLOriginal-tBRLOriginal;
      totalBRL=tBRL+taxas;
      comMarkup=true;
    }
    const ravVal=totalBRL*(parseFloat(rav)/100);
    const feeVal=parseFloat(fee)||0;
    const totalFinal=totalBRL+ravVal+feeVal;
    setResultado({p,tUSD,tBRL,totalBRL,ravVal,feeVal,totalFinal,tUSDOriginal,tBRLOriginal,totalBRLOriginal,comMarkup});
  };

  const fmtBRL=(v)=>'R$ '+v.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  const formatOutput=()=>{
    if(!resultado)return"";
    const{p,tUSD,tBRL,totalBRL,ravVal,feeVal,totalFinal,tUSDOriginal,tBRLOriginal,comMarkup}=resultado;
    const cab=cabine||p.fareFamily||"-";
    const comp=voo||"-";
    const bag=bagagem||"-";
    const rate=p.exchangeRate?`1 USD = R$ ${p.exchangeRate.toFixed(4)}`:"-";
    const sep="─".repeat(46);

    // ── OUTPUT PARA O CLIENTE ──
    let out=`Cia/Voo: ${comp}\nCabine: ${cab}\nBagagem: ${bag}\n${sep}\n`;
    out+=`Tarifa USD:           USD ${tUSD.toFixed(2).padStart(10)}\n`;
    out+=`Tarifa BRL:           ${fmtBRL(tBRL).padStart(18)}\n`;
    out+=`Taxas:                ${fmtBRL(totalBRL-tBRL).padStart(18)}\n`;
    out+=`RAV (${rav}%):            ${fmtBRL(ravVal).padStart(18)}\n`;
    out+=`FEE:                  ${fmtBRL(feeVal).padStart(18)}\n`;
    out+=`${sep}\n`;
    out+=`TOTAL FINAL:          ${fmtBRL(totalFinal).padStart(18)}\n`;
    out+=`${sep}\n`;
    out+=`Pagamento: ${parcelas}\n`;
    if(multaRem||multaReemb){
      out+=`\n[ REGRAS E PENALIDADES ]\n`;
      if(multaRem&&multaRem!=="N/A")out+=`Reemissão: USD ${multaRem}\n`;
      if(multaReemb&&multaReemb!=="N/A")out+=`Reembolso: USD ${multaReemb}\n`;
    }

    // ── CONFERÊNCIA (não enviar) ──
    out+=`\n${sep}\n--- CONFERÊNCIA (não enviar) ---\n${sep}\n`;
    if(comMarkup){
      out+=`Tarifa base USD:      USD ${tUSDOriginal.toFixed(2).padStart(10)}\n`;
      out+=`Markup (${markupPct}%):         USD ${(tUSD-tUSDOriginal).toFixed(2).padStart(10)}\n`;
      out+=`Tarifa c/ markup:     USD ${tUSD.toFixed(2).padStart(10)}\n`;
      out+=`Tarifa BRL c/ markup: ${fmtBRL(tBRL).padStart(18)}\n`;
    } else {
      out+=`Tarifa USD:           USD ${tUSD.toFixed(2).padStart(10)}\n`;
      out+=`Tarifa BRL:           ${fmtBRL(tBRL).padStart(18)}\n`;
    }
    out+=`Taxas:                ${fmtBRL(totalBRL-tBRL).padStart(18)}\n`;
    out+=`Total parcial:        ${fmtBRL(totalBRL).padStart(18)}\n`;
    out+=`RAV (${rav}%):            ${fmtBRL(ravVal).padStart(18)}\n`;
    out+=`FEE:                  ${fmtBRL(feeVal).padStart(18)}\n`;
    out+=`Câmbio: ${rate}`;
    return out;
  };

  const copiar=()=>{navigator.clipboard.writeText(formatOutput());setCopied(true);setTimeout(()=>setCopied(false),2000);};
  const limpar=()=>{setCotacao("");setResultado(null);setVoo("");setCabine("");setBagagem("");setMultaRem("");setMultaReemb("");};
  const p=cotacao?parseCotacao(cotacao,gds):null;
  const temDados=p&&(p.tUSD>0||p.totalBRL>0);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-black text-gray-900">Cálculo de Tarifas</h2>
        <Tab tabs={["AMADEUS","GALILEO","SABRE"]} active={gds} onChange={setGds} />
      </div>
      <Card>
        <Textarea label="Cole a cotação GDS aqui" value={cotacao} onChange={e=>setCotacao(e.target.value)} rows={7}
          placeholder={gds==="AMADEUS"?"USD 1857.00  26MAY26FOR IB X/MAD...\nBRL  9804.96  14.00 297.00...\nBRL 10139.24\nRATE USED 1USD=5.28BRL\nFARE FAMILY:FC1:1-2:COMFORT":gds==="GALILEO"?"FQG 1 BRL 1234.56 334.28 1568.84\nBSR 1USD-5.28":"USD 1234.56\nBRL 6521.67\nBRL 6856.84 ADT"} />
      </Card>
      {temDados&&(
        <Card className="bg-blue-50 border-blue-200">
          <div className="text-xs font-bold text-blue-600 mb-2">✓ Dados detectados automaticamente</div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
            <div><span className="text-gray-500">Base USD:</span> <strong>$ {p.tUSD.toFixed(2)}</strong></div>
            <div><span className="text-gray-500">Total BRL:</span> <strong>R$ {p.totalBRL.toFixed(2)}</strong></div>
            <div><span className="text-gray-500">Taxas:</span> <strong>R$ {p.taxesBRL.toFixed(2)}</strong></div>
            <div><span className="text-gray-500">Câmbio:</span> <strong>{p.exchangeRate?`R$ ${p.exchangeRate.toFixed(4)}`:"—"}</strong></div>
          </div>
          {p.fareFamily&&<div className="text-xs text-blue-600 mt-2">Cabine detectada: <strong>{p.fareFamily}</strong></div>}
        </Card>
      )}
      <Card>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          <Input label="Voo / Cia" value={voo} onChange={e=>setVoo(e.target.value)} placeholder="Ex: TAP, Iberia" />
          <Input label="Cabine" value={cabine} onChange={e=>setCabine(e.target.value)} placeholder={p?.fareFamily||"Ex: COMFORT"} />
          <Input label="Bagagem" value={bagagem} onChange={e=>setBagagem(e.target.value)} placeholder="Ex: 01PC de 23kg" />
        </div>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4 mt-4">
          <Input label="FEE (BRL)" type="number" value={fee} onChange={e=>setFee(e.target.value)} />
          <Input label="RAV %" type="number" value={rav} onChange={e=>setRav(e.target.value)} />
          <Input label="Parcelamento" value={parcelas} onChange={e=>setParcelas(e.target.value)} />
        </div>
        <div className="grid grid-cols-2 gap-4 mt-4">
          <Input label="Multa Reemissão (USD)" value={multaRem} onChange={e=>setMultaRem(e.target.value)} placeholder="Antes / Depois" />
          <Input label="Multa Reembolso (USD)" value={multaReemb} onChange={e=>setMultaReemb(e.target.value)} placeholder="Antes / Depois" />
        </div>
        <div className="border-t border-gray-100 mt-4 pt-4">
          <div className="flex items-center gap-2 mb-3">
            <input type="checkbox" id="markup" checked={markup} onChange={e=>setMarkup(e.target.checked)} className="w-4 h-4" />
            <label htmlFor="markup" className="text-sm text-gray-600 cursor-pointer">Aplicar Markup (tarifas net-net sem parcelamento)</label>
          </div>
          {markup&&(
            <div className="flex items-end gap-4">
              <div className="w-48"><Input label="Markup %" type="number" step="0.01" value={markupPct} onChange={e=>setMarkupPct(e.target.value)} placeholder="Ex: 10" /></div>
              <div className="text-xs text-gray-400 pb-2">Ex: 10% = divide por 0.90</div>
            </div>
          )}
        </div>
      </Card>
      <div className="flex gap-3">
        <Button onClick={calcular} disabled={!temDados}>🧮 Gerar</Button>
        <Button variant="secondary" onClick={copiar} disabled={!resultado}>{copied?"✓ Copiado!":"📋 Copiar"}</Button>
        <Button variant="secondary" onClick={limpar}>🗑 Limpar</Button>
      </div>
      {!temDados&&cotacao.length>10&&(
        <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-3 text-sm text-yellow-700">
          ⚠️ Não consegui detectar os dados. Verifique se a cotação contém <strong>USD</strong>, <strong>BRL total</strong> e <strong>RATE USED</strong>.
        </div>
      )}
      {resultado&&<Terminal>{formatOutput()}</Terminal>}
    </div>
  );
}
// ============================================================
// MÓDULO: CONVERSOR
// ============================================================
function ModuloConversor() {
  const [gds, setGds] = useState("AMADEUS");
  const [input, setInput] = useState("");
  const [output, setOutput] = useState("Aguardando itinerário...");
  const [copied, setCopied] = useState(false);

  const decodificar = () => {
    if (!input.trim()) return;
    const lines = input.trim().split("\n");
    const voos = [];
    for (const line of lines) {
      const match = line.match(
        /^\s*\d+\.?\s+([A-Z0-9]{2})\s*(\d{3,5})[A-Z]?\s+[A-Z]\s+(\d{1,2}[A-Z]{3})\s+[A-Z0-9]\s+([A-Z]{3})([A-Z]{3})\*?\s*\w+\s+(\d{3,4})\s+(\d{3,4})/
      );
      if (match) {
        const [, cia, num, data, orig, dest, dep4, arr4] = match;
        const origNome = AIRPORTS[orig] || orig;
        const destNome = AIRPORTS[dest] || dest;
        const ciaNome = AIRLINES[cia] || cia;
        const fmt = (t) => t.length === 3 ? `0${t[0]}:${t.slice(1)}` : `${t.slice(0,2)}:${t.slice(2)}`;
        voos.push(`${ciaNome.padEnd(12)} ${num.padStart(4,"0")} ➔ ${data.toUpperCase()} ➔ ${`${origNome} (${orig})`.padEnd(30)} ${fmt(dep4)} ➔ ${`${destNome} (${dest})`.padEnd(30)} ${fmt(arr4)}`);
      }
    }
    if (voos.length > 0) {
      setOutput(`*ITINERÁRIO DE VOO*\n${"─".repeat(90)}\n${voos.join("\n")}\n${"─".repeat(90)}\n_Gerado pelo Calcula Fácil_`);
    } else {
      setOutput(`⚠️ Não foi possível decodificar. Verifique o formato GDS.\n\nExemplos aceitos:\nAmadeus: 1 LA8150 Z 14MAY 3 FORLIS HK2  0840  2000  HRS /E\nSabre:   1 LA8150Z 14MAY Q FORLIS HK2 0840 2000\nGalileo: 1. LA8150 Z 14MAY3 FORLIS HK2 0840 2000`);
    }
  };

  const copiarZap = () => { navigator.clipboard.writeText(output); setCopied(true); setTimeout(() => setCopied(false), 2000); };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-black text-gray-900">Conversor de Itinerários</h2>
        <Tab tabs={["AMADEUS","SABRE","GALILEO"]} active={gds} onChange={setGds} />
      </div>
      <Card>
        <Textarea label="Cole as linhas de voo do GDS aqui" value={input} onChange={e => setInput(e.target.value)} rows={6}
          placeholder={gds==="AMADEUS"?"Ex: 1 LA8150 Z 14MAY 3 FORLIS HK2  0840  2000  HRS /E":gds==="SABRE"?"Ex: 1 LA8150Z 14MAY Q FORLIS HK2 0840 2000 HRS /E":"Ex: 1. LA8150 Z 14MAY3 FORLIS HK2 0840 2000"} />
      </Card>
      <div className="flex gap-3">
        <Button onClick={decodificar}>→ Decodificar</Button>
        <Button variant="secondary" onClick={copiarZap}>{copied ? "✓ Copiado!" : "📋 Copiar"}</Button>
      </div>
      <Terminal>{output}</Terminal>
      <Card className="bg-gray-50">
        <div className="text-xs font-bold text-gray-500 mb-3">DICIONÁRIO — AEROPORTOS PRINCIPAIS</div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs">
          {Object.entries(AIRPORTS).slice(0, 20).map(([code, name]) => (
            <div key={code} className="flex gap-1">
              <span className="font-mono font-bold text-blue-600">{code}</span>
              <span className="text-gray-600">{name}</span>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

// ============================================================
// MÓDULO: REEMISSÃO (ET* — original)
// ============================================================
function ModuloReemissao() {
  const [gds, setGds] = useState("AMADEUS");
  const [et, setEt] = useState("");
  const [result, setResult] = useState("Cole o resumo Amadeus (ET*) e clique em CALCULAR");
  const [copied, setCopied] = useState(false);
  const [form, setForm] = useState({
    cotacao:"5.5410",feeUSD:"25.00",ravPercent:"7.00",ravMinimo:"200",
    ticketOriginal:"",passageiro:"",passageiros:"",rota:"",roteiro:"",loc:"",
    dataEmissao:new Date().toISOString().split("T")[0],
    aplicarMarkup:false,markup:"10",
  });
  const upd = (k,v) => setForm(f => ({...f,[k]:v}));
  const extractVal = (texto,pattern) => { const m=texto.match(pattern); if(!m||!m[1])return 0; const p=parseFloat(m[1].trim().replace(/,/g,"")); return isNaN(p)?0:p; };
  const formatVal = (val) => { if(Math.abs(val)<0.01)return"0,00"; return val.toFixed(2).replace(".",","); };
  const formatDateBR = (d) => { if(!d)return""; const[y,m,dia]=d.split("-"); return`${dia}/${m}/${y}`; };

  const calcular = () => {
    const texto=et.trim().toUpperCase();
    if(!texto)return;
    const cotacao=parseFloat(form.cotacao.replace(",","."));
    const feeUSD=parseFloat(form.feeUSD.replace(",","."));
    const ravPercent=parseFloat(form.ravPercent.replace(",","."))/100;
    const ravMinimo=parseFloat(form.ravMinimo.replace(",","."));
    let oldBaseFareUSD=extractVal(texto,/OLD\s+BASE\s+FARE\s+USD\s+([\-\d,.]+)/i);
    let newBaseFareUSD=extractVal(texto,/NEW\s+BASE\s+FARE\s+USD\s+([\-\d,.]+)/i);
    let fareBalanceBRL=extractVal(texto,/FARE\s+BALANCE\s+BRL\s+([\-\d,.]+)/i);
    const taxBalanceBRL=extractVal(texto,/TAX\s+BALANCE\s+BRL\s+([\-\d,.]+)/i);
    const residualValueBRL=extractVal(texto,/RESIDUAL\s+VALUE\s+BRL\s+([\-\d,.]+)/i);
    const penaltyBRL=extractVal(texto,/PENALTY\s+BRL\s+([\-\d,.]+)/i);
    const ticketDiffBRL=extractVal(texto,/TICKET\s+DIFFERENCE\s+BRL\s+([\-\d,.]+)/i);
    const totalAddColBRL=extractVal(texto,/TOTAL\s+ADD\s+COLL\s+BRL\s+([\-\d,.]+)/i);
    const nonRefundableTax=extractVal(texto,/NON\s+REFUNDABLE\s+TAX\s+BRL\s+([\-\d,.]+)/i);
    const oldOriginal=oldBaseFareUSD, newOriginal=newBaseFareUSD;
    let comMarkup=false;

    // BASE DA TARIFA — prioridade: FARE BALANCE BRL > TICKET DIFFERENCE BRL
    let baseOriginalBRL = Math.abs(fareBalanceBRL) > 0.01
      ? fareBalanceBRL
      : ticketDiffBRL > 0 ? ticketDiffBRL : 0;

    // MARKUP — aplica SEMPRE em BRL sobre a base da tarifa
    let baseCalcBRL = baseOriginalBRL;
    if(form.aplicarMarkup && parseFloat(form.markup)>0){
      const mp = parseFloat(form.markup)/100;
      baseCalcBRL = baseOriginalBRL / (1 - mp);
      comMarkup = true;
    }

    // TAXAS
    let difTaxas = taxBalanceBRL;
    if(residualValueBRL<0) difTaxas = taxBalanceBRL + Math.abs(residualValueBRL);

    // RAV — somente sobre a diferença de TARIFA (não sobre taxas)
    const feeBRL = feeUSD * cotacao;
    let ravVal = 0;
    if(baseCalcBRL > 0){
      ravVal = baseCalcBRL * ravPercent;
      if(ravVal < ravMinimo) ravVal = ravMinimo;
    }

    const totalPorPax = baseCalcBRL + difTaxas + penaltyBRL + feeBRL + ravVal;
    const totalAddCollGDS = Math.abs(totalAddColBRL)>0.01
      ? totalAddColBRL
      : ticketDiffBRL>0
        ? ticketDiffBRL + penaltyBRL + Math.abs(residualValueBRL)
        : taxBalanceBRL + penaltyBRL + Math.abs(residualValueBRL);
    const totalAddCalc = baseOriginalBRL + difTaxas + penaltyBRL;
    const diffValid = Math.abs(totalAddCalc - totalAddCollGDS);
    const pad=12;
    const sep="─".repeat(42);

    // ── OUTPUT PARA O CLIENTE ──
    let out=`CÁLCULO DE REMARCAÇÃO - ADT\n`;
    out+=`Data: ${formatDateBR(form.dataEmissao)}\n`;
    out+=`Cotação USD: R$ ${cotacao.toFixed(4).replace(".",",")}\n`;
    out+=`FEE: U$ ${feeUSD.toFixed(2).replace(".",",")}\n`;
    out+=`${sep}\n\n`;
    if(form.passageiros.trim()){
      const paxLines=form.passageiros.trim().split("\n");
      out+=`PASSAGEIRO:  ${paxLines[0]}\n`;
      paxLines.slice(1).forEach(l=>out+=`             ${l}\n`);
      out+="\n";
    } else if(form.passageiro){
      out+=`PASSAGEIRO: ${form.passageiro}\n\n`;
    }
    if(form.roteiro.trim()){
      const rotLines=form.roteiro.trim().split("\n");
      out+=`ROTA:   ${rotLines[0]}\n`;
      rotLines.slice(1).forEach(l=>out+=`        ${l}\n`);
      out+="\n";
    } else if(form.rota){
      out+=`ROTA: ${form.rota}\n\n`;
    }
    if(form.loc)out+=`LOC.: ${form.loc}\n`;
    if(form.ticketOriginal)out+=`TICKET ORIGINAL: ${form.ticketOriginal}\n`;
    out+=`${sep}\n\n`;
    out+=`Diferença de tarifa (R$)     R$ ${formatVal(baseCalcBRL).padStart(pad)}\n`;
    out+=`Diferença de taxas           R$ ${formatVal(difTaxas).padStart(pad)}\n`;
    out+=`Multa                        R$ ${formatVal(penaltyBRL).padStart(pad)}\n`;
    out+=`FEE                          R$ ${formatVal(feeBRL).padStart(pad)}\n`;
    if(ravVal>0)out+=`RAV - ${(ravPercent*100).toFixed(0)}%                     R$ ${formatVal(ravVal).padStart(pad)}\n`;
    out+=`${sep}\n`;
    out+=`TOTAL POR PAX                R$ ${formatVal(totalPorPax).padStart(pad)}\n`;
    out+=`${"=".repeat(42)}\n`;
    out+=`***VALORES POR PAX SUJEITOS A ALTERAÇÃO***\n`;

    // ── CONFERÊNCIA (não enviar) ──
    out+=`\n${sep}\n--- CONFERÊNCIA (não enviar) ---\n${sep}\n`;
    if(oldOriginal>0){
      out+=`OLD BASE FARE: USD ${oldOriginal.toFixed(2)} = R$ ${formatVal(oldOriginal*cotacao)}\n`;
      out+=`NEW BASE FARE: USD ${newOriginal.toFixed(2)} = R$ ${formatVal(newOriginal*cotacao)}\n`;
    }
    out+=`FARE BALANCE (GDS):  R$ ${formatVal(baseOriginalBRL).padStart(pad)}\n`;
    if(comMarkup){
      out+=`Markup ${form.markup}%:          R$ ${formatVal(baseCalcBRL - baseOriginalBRL).padStart(pad)}\n`;
      out+=`FARE BALANCE c/mk:   R$ ${formatVal(baseCalcBRL).padStart(pad)}\n`;
    }
    out+=`TAX BALANCE:         R$ ${formatVal(difTaxas).padStart(pad)}\n`;
    out+=`PENALTY:             R$ ${formatVal(penaltyBRL).padStart(pad)}\n`;
    if(!comMarkup && Math.abs(totalAddCollGDS)>0.01){
      out+=`${sep}\n`;
      out+=`TOTAL ADD COLL (GDS): R$ ${formatVal(totalAddCollGDS).padStart(8)}\n`;
      out+=diffValid<0.01?`✅ VALIDAÇÃO: BATE COM O GDS\n`:`⚠️  DIFERENÇA: R$ ${formatVal(diffValid)}\n`;
    }
    if(residualValueBRL<0)out+=`* Taxas incluem compensação de residual negativo\n`;
    if(nonRefundableTax>0)out+=`* Non Refundable Tax (R$ ${formatVal(nonRefundableTax)}) não entra no cálculo\n`;
    setResult(out);
  };

  const copiar = () => { navigator.clipboard.writeText(result); setCopied(true); setTimeout(() => setCopied(false), 2000); };
  const limpar = () => { setEt(""); setForm(f=>({...f,ticketOriginal:"",passageiro:"",passageiros:"",rota:"",roteiro:"",loc:"",aplicarMarkup:false})); setResult("Cole o resumo Amadeus (ET*) e clique em CALCULAR"); };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-black text-gray-900">Comparação de Bilhetes — Reemissão</h2>
        <Tab tabs={["AMADEUS","GALILEO (OCR)","SABRE"]} active={gds} onChange={setGds} />
      </div>
      <Card>
        <Textarea label="Resumo ET* — Cole aqui" value={et} onChange={e=>setEt(e.target.value)} rows={7}
          placeholder={"Cole o conteúdo do resumo ET* aqui...\n\nExemplo:\nOLD BASE FARE       USD       795.00\nNEW BASE FARE       USD       795.00\nFARE BALANCE        BRL         0.00\nTAX BALANCE         BRL        24.00\nPENALTY             BRL       200.00\nTICKET DIFFERENCE   BRL       224.00\nTOTAL ADD COLL      BRL       224.00"} />
      </Card>
      <Card>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <Input label="Cotação do Dólar (R$)" type="number" step="0.0001" value={form.cotacao} onChange={e=>upd("cotacao",e.target.value)} />
          <Input label="FEE (USD)" type="number" step="0.01" value={form.feeUSD} onChange={e=>upd("feeUSD",e.target.value)} />
          <Input label="% RAV" type="number" step="0.01" value={form.ravPercent} onChange={e=>upd("ravPercent",e.target.value)} />
          <Input label="RAV Mínimo (R$)" type="number" value={form.ravMinimo} onChange={e=>upd("ravMinimo",e.target.value)} />
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4">
          <Input label="Ticket Original" value={form.ticketOriginal} onChange={e=>upd("ticketOriginal",e.target.value)} placeholder="Número do bilhete" />
          <Input label="Passageiro (simples)" value={form.passageiro} onChange={e=>upd("passageiro",e.target.value)} placeholder="Nome completo" />
          <Input label="Rota (simples)" value={form.rota} onChange={e=>upd("rota",e.target.value)} placeholder="Ex: GRU-MIA-JFK" />
          <Input label="Data" type="date" value={form.dataEmissao} onChange={e=>upd("dataEmissao",e.target.value)} />
        </div>
        <div className="grid grid-cols-3 gap-4 mt-4">
          <Textarea label="Passageiros (múltiplos)" value={form.passageiros} onChange={e=>upd("passageiros",e.target.value)} rows={3} placeholder={"1.SOBRENOME/NOME TITLE\n2.SOBRENOME/NOME TITLE"} />
          <Textarea label="Roteiro (voos GDS)" value={form.roteiro} onChange={e=>upd("roteiro",e.target.value)} rows={3} placeholder={"3 LA8084 L 23JAN 5 GRULHR HK2 2340 1405+1\n4 LX317 H 27JAN 2 LHRZRH HK2 0900 1155"} />
          <Input label="LOC (Localizador)" value={form.loc} onChange={e=>upd("loc",e.target.value)} placeholder="Ex: B2C7JN" />
        </div>
        <div className="border-t border-gray-100 mt-4 pt-4">
          <div className="flex items-center gap-2 mb-3">
            <input type="checkbox" id="markupReem" checked={form.aplicarMarkup} onChange={e=>upd("aplicarMarkup",e.target.checked)} className="w-4 h-4" />
            <label htmlFor="markupReem" className="text-sm text-gray-600 cursor-pointer">Aplicar Markup na tarifa (tarifas net-net)</label>
          </div>
          {form.aplicarMarkup&&(
            <div className="flex items-end gap-4">
              <div className="w-48"><Input label="Markup %" type="number" step="0.01" value={form.markup} onChange={e=>upd("markup",e.target.value)} placeholder="Ex: 10" /></div>
              <div className="text-xs text-gray-400 pb-2">Aplica fórmula: tarifa ÷ (1 - markup%)</div>
            </div>
          )}
        </div>
      </Card>
      <div className="flex gap-3">
        <Button onClick={calcular}>🧮 Calcular</Button>
        <Button variant="secondary" onClick={copiar} disabled={result==="Cole o resumo Amadeus (ET*) e clique em CALCULAR"}>{copied?"✓ Copiado!":"📋 Copiar"}</Button>
        <Button variant="secondary" onClick={limpar}>🗑 Limpar</Button>
      </div>
      <Terminal>{result}</Terminal>
    </div>
  );
}


// ============================================================
// MÓDULO: REEMISSÃO MANUAL (COLAR MÁSCARA GDS)
// ============================================================
function ModuloReemissaoManual() {
  const [mode, setMode] = useState('paste'); // 'paste' | 'manual'
  const [taNovo, setTaNovo] = useState('');
  const [taCred, setTaCred] = useState('');
  const [parseMsg, setParseMsg] = useState(null); // {text, ok}
  const [taxes, setTaxes] = useState([
    {code:'YQ',nova:49.69,cred:51.49},{code:'YR',nova:3751.96,cred:3244.18},
    {code:'AY',nova:27.82,cred:57.66},{code:'US1',nova:116.28,cred:120.49},
    {code:'US2',nova:19.08,cred:120.49},{code:'XA',nova:34.78,cred:19.77},
    {code:'XY',nova:36.72,cred:36.04},{code:'YC',nova:4.71,cred:38.05},
  ]);
  const [cfg, setCfg] = useState({ cambio:'5.0821', feeUSD:'30', rav:'200', ravPct:'7', markupPct:'0', penalty:'0' });
  const [oldUSD, setOldUSD] = useState('1258.00');
  const [newUSD, setNewUSD] = useState('1421.00');
  const [newCode, setNewCode] = useState('');
  const [newNova, setNewNova] = useState('');
  const [newCred, setNewCred] = useState('');
  const [copied, setCopied] = useState(false);
  const [mform, setMform] = useState({
    passageiro:'', passageiros:'', rota:'', roteiro:'', loc:'', ticketOriginal:'',
    dataEmissao: new Date().toISOString().split('T')[0],
  });
  const updM = (k,v) => setMform(f=>({...f,[k]:v}));

  const updCfg = (k,v) => setCfg(c=>({...c,[k]:v}));
  const taxDiff = (nova,cred) => Math.max(0, nova-cred);
  const brl = v => 'R$ '+v.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});

  // ── PARSERS ──
  const parseNovo = (text) => {
    const flat = text.replace(/\n/g,' ').replace(/\s+/g,' ');
    const usdM = flat.match(/USD\s+([\d,\.]+)/);
    const newU = usdM ? parseFloat(usdM[1].replace(',','.')) : null;
    const preXT = flat.split(' XT ')[0];
    const yqM = preXT.match(/BRL\s+([\d\.]+)-YQ/);
    const xtIdx = flat.indexOf(' XT ');
    if(xtIdx===-1) return {newUSD:newU, taxes:[]};
    const block = flat.substring(xtIdx+4);
    const tokens = block.split(/\s+/);
    const pairs = []; let pending = null;
    for(let i=0;i<tokens.length;i++){
      const t=tokens[i];
      if(t==='BRL'){
        const next=tokens[i+1]||'';
        const mN=next.match(/^([\d\.]+)(?:-([A-Z]{2,3}))?$/);
        if(!mN){i++;continue;}
        const val=parseFloat(mN[1]); const nc=mN[2]||null;
        if(nc==='XT'){pending=null;i++;continue;}
        if(pending){pairs.push({code:pending,val});pending=nc;}
        else{if(nc)pairs.push({code:nc,val});}
        i++;continue;
      }
      const mA=t.match(/^([\d\.]+)-([A-Z]{2,3})$/);
      if(mA){if(pending){pairs.push({code:pending,val:parseFloat(mA[1])});pending=mA[2];}else{pairs.push({code:mA[2],val:parseFloat(mA[1])});}continue;}
      const mC=t.match(/^-([A-Z]{2,3})$/);
      if(mC){pending=mC[1];continue;}
    }
    const clean=pairs.filter(p=>p.val>0&&p.code!=='XT');
    let usN=0;
    const result=clean.map(p=>{if(p.code==='US'){usN++;return{code:'US'+usN,val:p.val};}return p;});
    if(yqM)result.unshift({code:'YQ',val:parseFloat(yqM[1])});
    return {newUSD:newU, taxes:result};
  };

  const parseCredito = (text) => {
    const flat=text.replace(/\n/g,' ').replace(/\s+/g,' ');
    // Aceita: FARE USD, FARE R USD, FARE F USD, EQUIV USD
    const usdM=flat.match(/(?:FARE\s+[A-Z]?\s*USD|EQUIV\s+USD)\s+([\d\.]+)/i);
    const oldU=usdM?parseFloat(usdM[1]):null;
    let m;
    const rawMap={};

    // Formato 1: PD01 BRL 105.76BR ou TX01 BRL 105.76BR (prefixo sequencial)
    const pdRx=/(?:PD|TX)\d+\s+BRL\s+([\d\.]+)([A-Z]{2,3})/g;
    while((m=pdRx.exec(flat))!==null){
      rawMap[m[2]]=(rawMap[m[2]]||0)+parseFloat(m[1]);
    }

    // Formato 2: inline — BRL 105.76BR BRL 51.53QO (sem prefixo)
    // Roda sempre — ignora posições já capturadas pelo Formato 1
    const inlineRx=/BRL\s+([\d\.]+)([A-Z]{2,3})\b/g;
    while((m=inlineRx.exec(flat))!==null){
      const cod=m[2], val=parseFloat(m[1]);
      // Exclui códigos de moeda e totais
      if(cod==='USD'||cod==='BRL'||cod==='ADT'||cod==='NUC'||cod==='ROE')continue;
      // Só adiciona se ainda não foi capturado pelo Formato 1
      if(!(cod in rawMap)) rawMap[cod]=val;
    }

    const raw=Object.entries(rawMap).map(([code,val])=>({code,val}));
    let usN=0;
    const taxList=raw.map(p=>{if(p.code==='US'){usN++;return{code:'US'+usN,val:p.val};}return p;});
    return {oldUSD:oldU, taxes:taxList};
  };

  const processarMascara = () => {
    if(!taNovo.trim()||!taCred.trim()){setParseMsg({text:'Cole os dois blocos antes de processar.',ok:false});return;}
    try{
      const novo=parseNovo(taNovo);
      const cred=parseCredito(taCred);
      if(!novo.newUSD){setParseMsg({text:'USD não encontrado no bloco do novo valor.',ok:false});return;}
      if(!cred.oldUSD){setParseMsg({text:'FARE USD não encontrado no bilhete de crédito. Verifique se contém FARE USD, FARE R USD ou EQUIV USD.',ok:false});return;}
      if(novo.taxes.length===0){setParseMsg({text:'Nenhuma taxa encontrada.',ok:false});return;}
      setNewUSD(novo.newUSD.toFixed(2));
      setOldUSD(cred.oldUSD.toFixed(2));
      const credMap={};
      cred.taxes.forEach(t=>credMap[t.code]=t.val);
      const credUS=cred.taxes.filter(t=>t.code.startsWith('US'));
      const newTaxes=novo.taxes.map(t=>{
        let cv=0;
        if(t.code==='US1')cv=credUS[0]?credUS[0].val:0;
        else if(t.code==='US2')cv=credUS[1]?credUS[1].val:0;
        else cv=credMap[t.code]||0;
        return{code:t.code,nova:t.val,cred:cv};
      });
      setTaxes(newTaxes);
      setParseMsg({text:`✓ ${novo.taxes.length} taxas carregadas — Novo: USD ${novo.newUSD.toFixed(2)} | Crédito: USD ${cred.oldUSD.toFixed(2)}`,ok:true});
    }catch(e){setParseMsg({text:'Erro ao processar: '+e.message,ok:false});}
  };

  // ── CÁLCULOS ──
  const cambio=parseFloat(cfg.cambio)||0;
  const feeUSD=parseFloat(cfg.feeUSD)||0;
  const ravBRL=parseFloat(cfg.rav)||0;
  const penalty=parseFloat(cfg.penalty)||0;
  const oldBRL=(parseFloat(oldUSD)||0)*cambio;
  const newBRL=(parseFloat(newUSD)||0)*cambio;
  // Fare balance = diferença de tarifa em BRL
  const fareBalanceOriginal=Math.max(0,newBRL-oldBRL);
  // Markup aplicado em BRL sobre a diferença de tarifa
  const markupPctM=parseFloat(cfg.markupPct||'0')||0;
  const fareBalance=markupPctM>0 ? fareBalanceOriginal/(1-markupPctM/100) : fareBalanceOriginal;
  const taxBalance=taxes.reduce((s,t)=>s+taxDiff(t.nova,t.cred),0);
  const feeBRL=feeUSD*cambio;
  // RAV somente sobre diferença de TARIFA
  const ravCalc=fareBalance>0?Math.max(ravBRL, fareBalance*(parseFloat(cfg.ravPct||'0')||0)/100):0;
  const total=fareBalance+taxBalance+penalty+feeBRL+ravCalc;

  const updTax=(i,field,val)=>{
    setTaxes(tx=>tx.map((t,idx)=>idx===i?{...t,[field]:parseFloat(val)||0}:t));
  };
  const removeTax=(i)=>setTaxes(tx=>tx.filter((_,idx)=>idx!==i));
  const addTax=()=>{
    if(!newCode.trim())return;
    setTaxes(tx=>[...tx,{code:newCode.toUpperCase(),nova:parseFloat(newNova)||0,cred:parseFloat(newCred)||0}]);
    setNewCode('');setNewNova('');setNewCred('');
  };

  const formatValM=(v)=>{if(Math.abs(v)<0.01)return'0,00';return v.toFixed(2).replace('.',',');};
  const formatDateM=(d)=>{if(!d)return'';const[y,m,dia]=d.split('-');return`${dia}/${m}/${y}`;};
  const padM=12;
  const sepM='─'.repeat(42);

  const gerarTexto=()=>{
    const o=parseFloat(oldUSD)||0, n=parseFloat(newUSD)||0;

    // ── OUTPUT PARA O CLIENTE ──
    let out=`CÁLCULO DE REMARCAÇÃO - ADT\n`;
    out+=`Data: ${formatDateM(mform.dataEmissao)}\n`;
    out+=`Cotação USD: R$ ${cambio.toFixed(4).replace('.',',')}\n`;
    out+=`FEE: U$ ${feeUSD.toFixed(2).replace('.',',')}\n`;
    out+=`${sepM}\n\n`;
    if(mform.passageiros.trim()){
      const paxLines=mform.passageiros.trim().split('\n');
      out+=`PASSAGEIRO:  ${paxLines[0]}\n`;
      paxLines.slice(1).forEach(l=>out+=`             ${l}\n`);
      out+='\n';
    } else if(mform.passageiro){
      out+=`PASSAGEIRO: ${mform.passageiro}\n\n`;
    }
    if(mform.roteiro.trim()){
      const rotLines=mform.roteiro.trim().split('\n');
      out+=`ROTA:   ${rotLines[0]}\n`;
      rotLines.slice(1).forEach(l=>out+=`        ${l}\n`);
      out+='\n';
    } else if(mform.rota){
      out+=`ROTA: ${mform.rota}\n\n`;
    }
    if(mform.loc)out+=`LOC.: ${mform.loc}\n`;
    if(mform.ticketOriginal)out+=`TICKET ORIGINAL: ${mform.ticketOriginal}\n`;
    out+=`${sepM}\n\n`;
    out+=`Diferença de tarifa (R$)     R$ ${formatValM(fareBalance).padStart(padM)}\n`;
    out+=`Diferença de taxas           R$ ${formatValM(taxBalance).padStart(padM)}\n`;
    out+=`Multa                        R$ ${formatValM(penalty).padStart(padM)}\n`;
    out+=`FEE                          R$ ${formatValM(feeBRL).padStart(padM)}\n`;
    if(ravCalc>0)out+=`RAV                          R$ ${formatValM(ravCalc).padStart(padM)}\n`;
    out+=`${sepM}\n`;
    out+=`TOTAL POR PAX                R$ ${formatValM(total).padStart(padM)}\n`;
    out+=`${'='.repeat(42)}\n`;
    out+=`***VALORES POR PAX SUJEITOS A ALTERAÇÃO***\n`;

    // ── CONFERÊNCIA (não enviar) ──
    out+=`\n${sepM}\n--- CONFERÊNCIA (não enviar) ---\n${sepM}\n`;
    out+=`OLD BASE FARE: USD ${o.toFixed(2)} = ${brl(oldBRL)}\n`;
    out+=`NEW BASE FARE: USD ${n.toFixed(2)} = ${brl(newBRL)}\n`;
    out+=`FARE BALANCE (GDS):  ${brl(fareBalanceOriginal)}\n`;
    if(markupPctM>0){
      out+=`Markup ${markupPctM}%:          ${brl(fareBalance - fareBalanceOriginal)}\n`;
      out+=`FARE BALANCE c/mk:   ${brl(fareBalance)}\n`;
    }
    out+=`TAX BALANCE:         ${brl(taxBalance)}\n`;
    if(taxes.filter(t=>taxDiff(t.nova,t.cred)>0).length>0){
      out+=`Taxas com diferença:\n`;
      taxes.filter(t=>taxDiff(t.nova,t.cred)>0).forEach(t=>{
        out+=`  ${t.code.padEnd(6)} Nova: ${brl(t.nova).padEnd(14)} Créd: ${brl(t.cred).padEnd(14)} Dif: ${brl(taxDiff(t.nova,t.cred))}\n`;
      });
    }
    out+=`Câmbio: 1 USD = R$ ${cambio.toFixed(4)}`;
    return out;
  };

  const copiar=()=>{navigator.clipboard.writeText(gerarTexto());setCopied(true);setTimeout(()=>setCopied(false),2000);};

  const inputCls="w-full bg-gray-900 border border-gray-700 rounded text-sm font-mono text-green-400 px-2 py-1.5 text-right focus:outline-none focus:border-cyan-400";

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-black text-gray-900">Reemissão — Troca de Bilhete</h2>
        <div className="flex gap-1 bg-gray-100 rounded-xl p-1">
          <button onClick={()=>setMode('paste')}
            className={`px-4 py-1.5 rounded-lg text-xs font-mono font-bold transition-all ${mode==='paste'?'bg-gray-900 text-cyan-400 shadow':'text-gray-500 hover:text-gray-800'}`}>
            COLAR MÁSCARA
          </button>
          <button onClick={()=>setMode('manual')}
            className={`px-4 py-1.5 rounded-lg text-xs font-mono font-bold transition-all ${mode==='manual'?'bg-gray-900 text-cyan-400 shadow':'text-gray-500 hover:text-gray-800'}`}>
            MANUAL
          </button>
        </div>
      </div>

      {/* PASTE MODE */}
      {mode==='paste'&&(
        <div className="bg-gray-950 border border-gray-800 rounded-xl p-4 space-y-3">
          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <div className="text-xs font-mono text-gray-500 uppercase tracking-widest">Novo valor — cole aqui</div>
              <textarea value={taNovo} onChange={e=>setTaNovo(e.target.value)} rows={8}
                className="bg-gray-900 border border-gray-700 rounded-lg text-green-400 font-mono text-xs p-3 resize-y focus:outline-none focus:border-cyan-400"
                placeholder={"Cole aqui o bloco do novo valor\n(a partir da linha USD ...)"} />
            </div>
            <div className="flex flex-col gap-2">
              <div className="text-xs font-mono text-gray-500 uppercase tracking-widest">Bilhete de crédito — cole aqui</div>
              <textarea value={taCred} onChange={e=>setTaCred(e.target.value)} rows={8}
                className="bg-gray-900 border border-gray-700 rounded-lg text-green-400 font-mono text-xs p-3 resize-y focus:outline-none focus:border-cyan-400"
                placeholder={"Cole aqui o bloco do bilhete de crédito\n(FARE R USD ... + Taxas PD01...)"} />
            </div>
          </div>
          <button onClick={processarMascara}
            className="w-full py-3 bg-cyan-500/10 border border-cyan-500/40 text-cyan-400 font-mono text-sm font-bold rounded-lg hover:bg-cyan-500/20 transition-all">
            ⟶ PROCESSAR E CALCULAR
          </button>
          {parseMsg&&(
            <div className={`font-mono text-xs px-3 py-2 rounded border ${parseMsg.ok?'bg-green-500/10 border-green-500/30 text-green-400':'bg-red-500/10 border-red-500/30 text-red-400'}`}>
              {parseMsg.text}
            </div>
          )}
        </div>
      )}

      {/* CONFIG */}
      <div className="bg-white rounded-2xl border border-gray-100 p-5">
        <div className="text-xs font-mono font-bold text-gray-400 uppercase tracking-widest mb-4">Configuração</div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {[
            {label:'CÂMBIO (1 USD =)',key:'cambio',unit:'BRL'},
            {label:'FEE AGÊNCIA',key:'feeUSD',unit:'USD'},
            {label:'RAV MÍNIMO',key:'rav',unit:'BRL'},
            {label:'RAV %',key:'ravPct',unit:'%'},
            {label:'MARKUP %',key:'markupPct',unit:'%'},
            {label:'PENALIDADE',key:'penalty',unit:'BRL'},
          ].map(f=>(
            <div key={f.key} className="flex flex-col gap-1">
              <label className="text-xs font-mono text-gray-400">{f.label}</label>
              <div className="relative">
                <input type="number" value={cfg[f.key]} onChange={e=>updCfg(f.key,e.target.value)}
                  className="w-full bg-gray-50 border border-gray-200 rounded px-2 py-1.5 text-sm font-mono focus:outline-none focus:border-blue-500 pr-10" />
                <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-gray-400 font-mono">{f.unit}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* TARIFA BASE */}
      <div className="bg-white rounded-2xl border border-gray-100 p-5">
        <div className="text-xs font-mono font-bold text-gray-400 uppercase tracking-widest mb-4">Tarifa Base</div>
        <div className="grid grid-cols-2 gap-6">
          <div className="flex flex-col gap-1">
            <label className="text-xs font-mono text-gray-400">OLD BASE FARE</label>
            <div className="relative">
              <input type="number" value={oldUSD} onChange={e=>setOldUSD(e.target.value)}
                className="w-full bg-gray-50 border border-gray-200 rounded px-2 py-1.5 text-sm font-mono focus:outline-none focus:border-blue-500 pr-10" />
              <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-gray-400 font-mono">USD</span>
            </div>
            <div className="text-xs text-gray-400 font-mono">= {brl(oldBRL)}</div>
          </div>
          <div className="flex flex-col gap-1">
            <label className="text-xs font-mono text-gray-400">NEW BASE FARE</label>
            <div className="relative">
              <input type="number" value={newUSD} onChange={e=>setNewUSD(e.target.value)}
                className="w-full bg-gray-50 border border-gray-200 rounded px-2 py-1.5 text-sm font-mono focus:outline-none focus:border-blue-500 pr-10" />
              <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-gray-400 font-mono">USD</span>
            </div>
            <div className="text-xs text-gray-400 font-mono">= {brl(newBRL)}</div>
          </div>
        </div>
        <div className="mt-3 pt-3 border-t border-gray-100 text-sm font-mono font-bold text-gray-700">
          FARE BALANCE: <span className={fareBalance>0?'text-orange-500':'text-gray-400'}>{brl(fareBalance)}</span>
        </div>
      </div>

      {/* TAXAS */}
      <div className="bg-white rounded-2xl border border-gray-100 p-5">
        <div className="text-xs font-mono font-bold text-gray-400 uppercase tracking-widest mb-4">Taxas</div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm font-mono">
            <thead>
              <tr className="text-xs text-gray-400 border-b border-gray-100">
                <th className="text-left py-2 w-16">CÓD</th>
                <th className="text-right py-2">NOVA (BRL)</th>
                <th className="text-right py-2">CRÉDITO (BRL)</th>
                <th className="text-right py-2 text-orange-400">DIFERENÇA</th>
                <th className="w-8"></th>
              </tr>
            </thead>
            <tbody>
              {taxes.map((t,i)=>{
                const d=taxDiff(t.nova,t.cred);
                return(
                  <tr key={i} className="border-b border-gray-50">
                    <td className="py-1.5 text-cyan-600 font-bold">{t.code}</td>
                    <td className="py-1.5 px-1">
                      <input type="number" value={t.nova} step="0.01"
                        onChange={e=>updTax(i,'nova',e.target.value)}
                        className={inputCls} />
                    </td>
                    <td className="py-1.5 px-1">
                      <input type="number" value={t.cred} step="0.01"
                        onChange={e=>updTax(i,'cred',e.target.value)}
                        className={inputCls} />
                    </td>
                    <td className={`py-1.5 text-right font-bold ${d>0?'text-orange-500':'text-gray-200'}`}>
                      {d>0?brl(d):'—'}
                    </td>
                    <td className="py-1.5 text-center">
                      <button onClick={()=>removeTax(i)} className="text-gray-300 hover:text-red-400 transition-colors text-lg leading-none">×</button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <div className="flex gap-2 mt-3 pt-3 border-t border-dashed border-gray-200 items-center">
          <input type="text" placeholder="CÓD" maxLength={4} value={newCode} onChange={e=>setNewCode(e.target.value)}
            className="w-16 bg-gray-50 border border-gray-200 rounded px-2 py-1.5 text-sm font-mono uppercase focus:outline-none focus:border-blue-500" />
          <input type="number" placeholder="Nova" value={newNova} onChange={e=>setNewNova(e.target.value)}
            className="w-28 bg-gray-50 border border-gray-200 rounded px-2 py-1.5 text-sm font-mono focus:outline-none focus:border-blue-500 text-right" />
          <input type="number" placeholder="Crédito" value={newCred} onChange={e=>setNewCred(e.target.value)}
            className="w-28 bg-gray-50 border border-gray-200 rounded px-2 py-1.5 text-sm font-mono focus:outline-none focus:border-blue-500 text-right" />
          <button onClick={addTax}
            className="px-3 py-1.5 bg-cyan-50 border border-cyan-300 text-cyan-700 rounded text-xs font-mono font-bold hover:bg-cyan-100 transition-all whitespace-nowrap">
            + Adicionar
          </button>
        </div>
        <div className="mt-3 pt-3 border-t border-gray-100 text-sm font-mono font-bold text-gray-700">
          TAX BALANCE: <span className={taxBalance>0?'text-orange-500':'text-gray-400'}>{brl(taxBalance)}</span>
        </div>
      </div>

      {/* RESUMO */}
      <div className="bg-gray-950 border border-cyan-500/30 rounded-2xl p-5">
        <div className="text-xs font-mono font-bold text-gray-500 uppercase tracking-widest mb-4">Resumo</div>
        {[
          {label:'OLD BASE FARE',val:`USD ${(parseFloat(oldUSD)||0).toFixed(2)} = ${brl(oldBRL)}`},
          {label:'NEW BASE FARE',val:`USD ${(parseFloat(newUSD)||0).toFixed(2)} = ${brl(newBRL)}`},
          {label:'FARE BALANCE',val:brl(fareBalance)},
          {label:'TAX BALANCE',val:brl(taxBalance)},
          {label:'PENALTY',val:brl(penalty)},
          {label:`FEE  USD ${feeUSD} × ${cambio}`,val:brl(feeBRL)},
          {label:'RAV',val:brl(ravCalc)},
        ].map(r=>(
          <div key={r.label} className="flex justify-between items-baseline py-2 border-b border-gray-800 text-sm font-mono">
            <span className="text-gray-500">{r.label}</span>
            <span className="text-gray-300">{r.val}</span>
          </div>
        ))}
        <div className="flex justify-between items-baseline pt-4 mt-2 border-t border-cyan-500/40">
          <span className="text-white font-mono font-bold">TOTAL A COBRAR</span>
          <span className="text-orange-400 font-mono font-bold text-2xl">{brl(total)}</span>
        </div>
      </div>

      {/* DADOS DO CLIENTE */}
      <div className="bg-white rounded-2xl border border-gray-100 p-5">
        <div className="text-xs font-mono font-bold text-gray-400 uppercase tracking-widest mb-4">Dados para o cliente</div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
          <Input label="Data" type="date" value={mform.dataEmissao} onChange={e=>updM('dataEmissao',e.target.value)} />
          <Input label="Passageiro (simples)" value={mform.passageiro} onChange={e=>updM('passageiro',e.target.value)} placeholder="Nome completo" />
          <Input label="LOC (Localizador)" value={mform.loc} onChange={e=>updM('loc',e.target.value)} placeholder="Ex: B2C7JN" />
          <Input label="Ticket Original" value={mform.ticketOriginal} onChange={e=>updM('ticketOriginal',e.target.value)} placeholder="Número do bilhete" />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <Textarea label="Passageiros (múltiplos)" value={mform.passageiros} onChange={e=>updM('passageiros',e.target.value)}
            rows={3} placeholder={"1.SOBRENOME/NOME TITLE\n2.SOBRENOME/NOME TITLE"} />
          <Textarea label="Roteiro (voos GDS)" value={mform.roteiro} onChange={e=>updM('roteiro',e.target.value)}
            rows={3} placeholder={"3 AF415 A 10MAY 7 FORCDG HK2 1955 0925\n4 AF111 Y 26JUN 4 PVGCDG HK1 2130 0550+1"} />
        </div>
        <div className="mt-3">
          <Input label="Rota (simples)" value={mform.rota} onChange={e=>updM('rota',e.target.value)} placeholder="Ex: GRU-CDG-NRT" />
        </div>
      </div>

      <div className="flex gap-3">
        <Button onClick={copiar}>{copied?'✓ Copiado!':'📋 Copiar resultado'}</Button>
        <Button variant="secondary" onClick={()=>{setTaxes([]);setTaNovo('');setTaCred('');setParseMsg(null);setMform({passageiro:'',passageiros:'',rota:'',roteiro:'',loc:'',ticketOriginal:'',dataEmissao:new Date().toISOString().split('T')[0]});}}>🗑 Limpar</Button>
      </div>
    </div>
  );
}


// ============================================================
// CONFIGURAÇÕES
// ============================================================
function ConfiguracoesSistema() {
  const [cfg, setCfg] = useState({ preco_individual:"49.99", preco_empresarial:"49.99", dias_trial:"5", rav_padrao:"7", fee_padrao:"157.76", rav_minimo:"200" });
  const [saving, setSaving] = useState("");
  const [msg, setMsg] = useState("");

  useEffect(() => {
    supabase.from("configuracoes").select("*").single().then(({ data }) => { if(data)setCfg(c=>({...c,...data})); });
  }, []);

  const salvar = async (campos, label) => {
    setSaving(label); setMsg("");
    const { error } = await supabase.from("configuracoes").upsert({ id:1,...campos }, { onConflict:"id" });
    setSaving(""); setMsg(error?"❌ Erro ao salvar.":`✅ ${label} salvo!`);
    setTimeout(() => setMsg(""), 3000);
  };
  const upd = (k,v) => setCfg(c=>({...c,[k]:v}));

  return (
    <>
      <h2 className="text-2xl font-black text-gray-900">Configurações do Sistema</h2>
      {msg&&<div className={`p-3 rounded-xl text-sm font-semibold ${msg.startsWith("✅")?"bg-green-50 text-green-700":"bg-red-50 text-red-600"}`}>{msg}</div>}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card>
          <h3 className="font-bold text-gray-800 mb-4">💰 Planos e Preços</h3>
          <div className="space-y-3">
            <Input label="Preço Individual (R$/mês)" value={cfg.preco_individual} onChange={e=>upd("preco_individual",e.target.value)} />
            <Input label="Preço por Acesso Empresarial (R$/mês)" value={cfg.preco_empresarial} onChange={e=>upd("preco_empresarial",e.target.value)} />
            <Input label="Dias de Trial Gratuito" value={cfg.dias_trial} onChange={e=>upd("dias_trial",e.target.value)} />
          </div>
          <Button className="mt-4" disabled={saving==="Preços"} onClick={()=>salvar({preco_individual:cfg.preco_individual,preco_empresarial:cfg.preco_empresarial,dias_trial:cfg.dias_trial},"Preços")}>
            {saving==="Preços"?"Salvando...":"Salvar Preços"}
          </Button>
        </Card>
        <Card>
          <h3 className="font-bold text-gray-800 mb-4">🧮 Padrões de Cálculo</h3>
          <div className="space-y-3">
            <Input label="RAV Padrão (%)" value={cfg.rav_padrao} onChange={e=>upd("rav_padrao",e.target.value)} />
            <Input label="FEE Padrão (BRL)" value={cfg.fee_padrao} onChange={e=>upd("fee_padrao",e.target.value)} />
            <Input label="RAV Mínimo Reemissão (R$)" value={cfg.rav_minimo} onChange={e=>upd("rav_minimo",e.target.value)} />
          </div>
          <Button className="mt-4" disabled={saving==="Padrões"} onClick={()=>salvar({rav_padrao:cfg.rav_padrao,fee_padrao:cfg.fee_padrao,rav_minimo:cfg.rav_minimo},"Padrões")}>
            {saving==="Padrões"?"Salvando...":"Salvar Padrões"}
          </Button>
        </Card>
      </div>
    </>
  );
}

// ============================================================
// PAINEL ADMIN — mantém original, remove WhatsApp do recibo
// ============================================================
function PainelAdmin({ onLogout }) {
  const [tab, setTab] = useState("Dashboard");
  const [users, setUsers] = useState([]);
  const [pagamentos, setPagamentos] = useState([]);
  const [loadingUsers, setLoadingUsers] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [showAcaoModal, setShowAcaoModal] = useState(false);
  const [userSelecionado, setUserSelecionado] = useState(null);
  const [novoUser, setNovoUser] = useState({ name:"", email:"", plan:"trial", trialDays:5 });
  const [savingUser, setSavingUser] = useState(false);
  const [userMsg, setUserMsg] = useState("");
  const [pagForm, setPagForm] = useState({ valor:"49.99", metodo:"PIX", obs:"" });

  const carregarUsuarios = async () => {
    setLoadingUsers(true);
    const { data } = await supabase.from("profiles").select("*").order("created_at",{ascending:false});
    if(data)setUsers(data);
    setLoadingUsers(false);
  };

  const carregarPagamentos = async () => {
    const { data } = await supabase.from("pagamentos").select("*, profiles(full_name, email)").order("created_at",{ascending:false});
    if(data)setPagamentos(data);
  };

  useEffect(() => {
    if(tab==="Usuários")carregarUsuarios();
    if(tab==="Pagamentos"||tab==="Dashboard"){carregarUsuarios();carregarPagamentos();}
  }, [tab]);

  const atualizarStatus = async (id, campos) => {
    await supabase.from("profiles").update(campos).eq("id",id);
    carregarUsuarios(); setShowAcaoModal(false);
  };

  const ativarPlano = (u) => atualizarStatus(u.id, { plan:"individual", blocked:false, paid_until:new Date(Date.now()+30*24*60*60*1000).toISOString() });
  const bloquear = (u) => atualizarStatus(u.id, { blocked:true });
  const desbloquear = (u) => atualizarStatus(u.id, { blocked:false });
  const cancelarAcesso = (u) => atualizarStatus(u.id, { plan:"cancelado", blocked:true });

  const registrarPagamento = async (u) => {
    await supabase.from("pagamentos").insert({ user_id:u.id, valor:parseFloat(pagForm.valor), metodo:pagForm.metodo, obs:pagForm.obs, status:"pago" });
    await ativarPlano(u);
    carregarPagamentos();
    setShowAcaoModal(false);
  };

  const criarUsuario = async () => {
    setSavingUser(true); setUserMsg("");
    try {
      const { error } = await supabase.auth.signUp({
        email: novoUser.email, password: Math.random().toString(36).slice(-10)+"A1!",
        options: { data: { full_name:novoUser.name } }
      });
      if(error){setUserMsg("Erro: "+error.message);setSavingUser(false);return;}
      setUserMsg("✅ Usuário criado! Oriente a redefinir a senha via 'Esqueci minha senha'.");
      setTimeout(()=>{setShowModal(false);setUserMsg("");carregarUsuarios();},2500);
    } catch(e){setUserMsg("Erro inesperado.");}
    setSavingUser(false);
  };

  const trialDaysLeft = (u) => {
    if(!u.trial_start)return 0;
    const diff=(new Date()-new Date(u.trial_start))/(1000*60*60*24);
    return Math.max(0,5-Math.floor(diff));
  };

  const getStatus = (u) => {
    if(u.plan==="cancelado")return{label:"Cancelado",color:"gray"};
    if(u.blocked)return{label:"Bloqueado",color:"red"};
    if(u.plan==="trial")return{label:`Trial (${trialDaysLeft(u)}d)`,color:trialDaysLeft(u)<=1?"red":"yellow"};
    if(u.plan==="individual"||u.plan==="empresarial")return{label:"Ativo",color:"green"};
    if(u.plan==="admin")return{label:"Admin",color:"purple"};
    return{label:u.plan,color:"gray"};
  };

  const totalReceita=pagamentos.filter(p=>p.status==="pago").reduce((a,p)=>a+(p.valor||0),0);
  const totalUsuarios=users.filter(u=>u.role!=="admin").length;
  const ativos=users.filter(u=>(u.plan==="individual"||u.plan==="empresarial")&&!u.blocked).length;
  const trials=users.filter(u=>u.plan==="trial"&&!u.blocked).length;
  const bloqueados=users.filter(u=>u.blocked).length;
  const vencendoHoje=users.filter(u=>u.plan==="trial"&&trialDaysLeft(u)<=1&&!u.blocked).length;

  const menus = [
    {id:"Dashboard",icon:"📊",grupo:"admin"},{id:"Usuários",icon:"👥",grupo:"admin"},
    {id:"Pagamentos",icon:"💰",grupo:"admin"},{id:"Configurações",icon:"⚙️",grupo:"admin"},
    {id:"Tarifas",icon:"🧮",grupo:"ferramentas"},{id:"Conversor",icon:"✈️",grupo:"ferramentas"},{id:"Reemissão",icon:"🔄",grupo:"ferramentas"},{id:"Reemissão Manual",icon:"🔁",grupo:"ferramentas"},
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      {showModal&&(
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-md">
            <h3 className="font-black text-lg text-gray-900 mb-4">➕ Novo Usuário</h3>
            <div className="space-y-3">
              <Input label="Nome completo" value={novoUser.name} onChange={e=>setNovoUser({...novoUser,name:e.target.value})} placeholder="Nome do usuário" />
              <Input label="E-mail" type="email" value={novoUser.email} onChange={e=>setNovoUser({...novoUser,email:e.target.value})} placeholder="email@exemplo.com" />
              <div className="flex flex-col gap-1">
                <label className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Plano inicial</label>
                <select value={novoUser.plan} onChange={e=>setNovoUser({...novoUser,plan:e.target.value})}
                  className="border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                  <option value="trial">Trial</option>
                  <option value="individual">Individual (pago)</option>
                  <option value="empresarial">Empresarial</option>
                </select>
              </div>
              {userMsg&&<div className={`text-sm p-3 rounded-lg ${userMsg.startsWith("✅")?"bg-green-50 text-green-700":"bg-red-50 text-red-600"}`}>{userMsg}</div>}
            </div>
            <div className="flex gap-3 mt-5">
              <Button onClick={criarUsuario} disabled={savingUser||!novoUser.email||!novoUser.name}>{savingUser?"Criando...":"✅ Criar Usuário"}</Button>
              <Button variant="secondary" onClick={()=>{setShowModal(false);setUserMsg("");}}>Cancelar</Button>
            </div>
          </div>
        </div>
      )}

      {showAcaoModal&&userSelecionado&&(
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-lg">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-lg text-gray-900">⚙️ Gerenciar Usuário</h3>
              <button onClick={()=>setShowAcaoModal(false)} className="text-gray-400 hover:text-gray-600 text-xl">×</button>
            </div>
            <div className="bg-gray-50 rounded-xl p-3 mb-4">
              <div className="font-bold text-gray-800">{userSelecionado.full_name}</div>
              <div className="text-sm text-gray-500">{userSelecionado.email}</div>
              <div className="mt-1"><Badge color={getStatus(userSelecionado).color}>{getStatus(userSelecionado).label}</Badge></div>
            </div>
            <div className="grid grid-cols-2 gap-3 mb-4">
              <Button variant="success" onClick={()=>ativarPlano(userSelecionado)}>✅ Ativar Plano (30d)</Button>
              {!userSelecionado.blocked
                ?<Button variant="danger" onClick={()=>bloquear(userSelecionado)}>🔴 Bloquear</Button>
                :<Button variant="success" onClick={()=>desbloquear(userSelecionado)}>🟢 Desbloquear</Button>}
              <Button variant="secondary" onClick={()=>cancelarAcesso(userSelecionado)} className="text-gray-500">⚫ Cancelar Acesso</Button>
            </div>
            <div className="border-t border-gray-100 pt-4">
              <div className="text-xs font-bold text-gray-500 uppercase mb-3">💰 Registrar Pagamento PIX</div>
              <div className="grid grid-cols-2 gap-3 mb-3">
                <Input label="Valor (R$)" type="number" value={pagForm.valor} onChange={e=>setPagForm({...pagForm,valor:e.target.value})} />
                <div className="flex flex-col gap-1">
                  <label className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Método</label>
                  <select value={pagForm.metodo} onChange={e=>setPagForm({...pagForm,metodo:e.target.value})}
                    className="border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                    <option>PIX</option><option>Cartão</option><option>Transferência</option><option>Dinheiro</option>
                  </select>
                </div>
              </div>
              <Input label="Observação (opcional)" value={pagForm.obs} onChange={e=>setPagForm({...pagForm,obs:e.target.value})} placeholder="Ex: Mensalidade março" />
              <div className="flex gap-3 mt-3">
                <Button variant="success" onClick={()=>registrarPagamento(userSelecionado)}>💰 Confirmar Pagamento + Ativar</Button>
              </div>
            </div>
          </div>
        </div>
      )}

      <header className="bg-slate-900 text-white px-6 py-4 flex items-center justify-between border-b border-slate-700">
        <div className="flex items-center gap-4">
          <span className="text-xl font-black">⚡ Calcula Fácil</span>
          <span className="bg-purple-600 text-white text-xs font-bold px-2 py-0.5 rounded-full">ADMIN MASTER</span>
        </div>
        <div className="flex items-center gap-4">
          <span className="text-slate-300 text-sm">● Geraldo — geraldofor@gmail.com</span>
          <button onClick={onLogout} className="text-xs bg-slate-700 hover:bg-slate-600 px-3 py-1.5 rounded-lg transition-all">Sair</button>
        </div>
      </header>

      <div className="flex">
        <aside className="w-56 bg-white border-r border-gray-200 min-h-[calc(100vh-60px)] p-4">
          <div className="text-xs font-bold text-gray-400 uppercase tracking-wide mb-3 px-3">Administração</div>
          {menus.filter(m=>m.grupo==="admin").map(m=>(
            <button key={m.id} onClick={()=>setTab(m.id)}
              className={`w-full text-left px-3 py-2.5 rounded-xl text-sm font-medium mb-1 transition-all flex items-center gap-2 ${tab===m.id?"bg-blue-600 text-white shadow":"text-gray-600 hover:bg-gray-100"}`}>
              <span>{m.icon}</span>{m.id}
              {m.id==="Usuários"&&vencendoHoje>0&&<span className="ml-auto bg-red-500 text-white text-xs px-1.5 py-0.5 rounded-full">{vencendoHoje}</span>}
            </button>
          ))}
          <div className="text-xs font-bold text-gray-400 uppercase tracking-wide mb-3 px-3 mt-5">Ferramentas</div>
          {menus.filter(m=>m.grupo==="ferramentas").map(m=>(
            <button key={m.id} onClick={()=>setTab(m.id)}
              className={`w-full text-left px-3 py-2.5 rounded-xl text-sm font-medium mb-1 transition-all flex items-center gap-2 ${tab===m.id?"bg-green-600 text-white shadow":"text-gray-600 hover:bg-gray-100"}`}>
              <span>{m.icon}</span>{m.id}
            </button>
          ))}
        </aside>

        <main className="flex-1 p-6 space-y-6">
          {tab==="Dashboard"&&(
            <>
              <h2 className="text-2xl font-black text-gray-900">Dashboard</h2>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                  {label:"Receita do Mês",valor:`R$ ${totalReceita.toFixed(2)}`,cor:"text-green-600",bg:"bg-green-50 border-green-200",icon:"💰"},
                  {label:"Assinantes Ativos",valor:ativos,cor:"text-blue-600",bg:"bg-blue-50 border-blue-200",icon:"✅"},
                  {label:"Em Trial",valor:trials,cor:"text-yellow-600",bg:"bg-yellow-50 border-yellow-200",icon:"⏳"},
                  {label:"Bloqueados",valor:bloqueados,cor:"text-red-500",bg:"bg-red-50 border-red-200",icon:"🔴"},
                ].map(m=>(
                  <div key={m.label} className={`rounded-2xl border p-5 ${m.bg}`}>
                    <div className="text-2xl mb-1">{m.icon}</div>
                    <div className={`text-3xl font-black ${m.cor}`}>{m.valor}</div>
                    <div className="text-xs text-gray-500 mt-1">{m.label}</div>
                  </div>
                ))}
              </div>
              {vencendoHoje>0&&(
                <div className="bg-red-50 border border-red-200 rounded-2xl p-4">
                  <div className="font-bold text-red-700 mb-2">⚠️ Trials vencendo hoje ({vencendoHoje})</div>
                  {users.filter(u=>u.plan==="trial"&&trialDaysLeft(u)<=1&&!u.blocked).map(u=>(
                    <div key={u.id} className="flex items-center justify-between py-1 border-b border-red-100 last:border-0">
                      <div><span className="font-medium">{u.full_name}</span> <span className="text-sm text-gray-500">{u.email}</span></div>
                      <Button variant="success" className="text-xs py-1 px-2" onClick={()=>{setUserSelecionado(u);setShowAcaoModal(true);}}>Gerenciar</Button>
                    </div>
                  ))}
                </div>
              )}
              <Card>
                <h3 className="font-bold text-gray-800 mb-4">📋 Últimos Pagamentos</h3>
                {pagamentos.length===0?(
                  <div className="text-center text-gray-400 py-6">Nenhum pagamento registrado ainda.</div>
                ):(
                  <table className="w-full text-sm">
                    <thead><tr className="text-xs text-gray-400 border-b">
                      <th className="text-left py-2">Usuário</th><th className="text-left py-2">Valor</th>
                      <th className="text-left py-2">Método</th><th className="text-left py-2">Data</th><th className="text-left py-2">Obs</th>
                    </tr></thead>
                    <tbody>{pagamentos.slice(0,10).map(p=>(
                      <tr key={p.id} className="border-b border-gray-50 hover:bg-gray-50">
                        <td className="py-2"><div className="font-medium">{p.profiles?.full_name||"—"}</div><div className="text-xs text-gray-400">{p.profiles?.email}</div></td>
                        <td className="font-bold text-green-600">R$ {(p.valor||0).toFixed(2)}</td>
                        <td>{p.metodo}</td>
                        <td className="text-gray-400">{new Date(p.created_at).toLocaleDateString("pt-BR")}</td>
                        <td className="text-gray-500 text-xs">{p.obs||"—"}</td>
                      </tr>
                    ))}</tbody>
                  </table>
                )}
              </Card>
            </>
          )}
          {tab==="Usuários"&&(
            <>
              <div className="flex items-center justify-between">
                <h2 className="text-2xl font-black text-gray-900">Gestão de Usuários</h2>
                <Button onClick={()=>setShowModal(true)}>+ Novo Usuário</Button>
              </div>
              <div className="grid grid-cols-4 gap-4">
                <Card className="text-center"><div className="text-2xl font-black text-blue-600">{totalUsuarios}</div><div className="text-xs text-gray-500">Total</div></Card>
                <Card className="text-center"><div className="text-2xl font-black text-green-600">{ativos}</div><div className="text-xs text-gray-500">Ativos</div></Card>
                <Card className="text-center"><div className="text-2xl font-black text-yellow-500">{trials}</div><div className="text-xs text-gray-500">Em Trial</div></Card>
                <Card className="text-center"><div className="text-2xl font-black text-red-500">{bloqueados}</div><div className="text-xs text-gray-500">Bloqueados</div></Card>
              </div>
              <Card>
                {loadingUsers?(
                  <div className="text-center text-gray-400 py-8">Carregando usuários...</div>
                ):(
                  <table className="w-full text-sm">
                    <thead><tr className="text-xs text-gray-400 border-b">
                      <th className="text-left py-2">Usuário</th><th className="text-left py-2">Plano</th>
                      <th className="text-left py-2">Status</th><th className="text-left py-2">Cadastro</th><th className="text-left py-2">Ações</th>
                    </tr></thead>
                    <tbody>{users.map(u=>{
                      const st=getStatus(u);
                      return(
                        <tr key={u.id} className="border-b border-gray-50 hover:bg-gray-50">
                          <td className="py-2"><div className="font-medium">{u.full_name||"—"}</div><div className="text-xs text-gray-400">{u.email}</div></td>
                          <td><Badge color={u.role==="admin"?"purple":u.plan==="individual"?"blue":u.plan==="empresarial"?"green":"yellow"}>{u.plan}</Badge></td>
                          <td><Badge color={st.color}>{st.label}</Badge></td>
                          <td className="text-gray-400">{new Date(u.created_at).toLocaleDateString("pt-BR")}</td>
                          <td>{u.role!=="admin"?(<Button variant="secondary" className="text-xs py-1 px-3" onClick={()=>{setUserSelecionado(u);setShowAcaoModal(true);}}>⚙️ Gerenciar</Button>):<Badge color="purple">MASTER</Badge>}</td>
                        </tr>
                      );
                    })}</tbody>
                  </table>
                )}
              </Card>
            </>
          )}
          {tab==="Pagamentos"&&(
            <>
              <h2 className="text-2xl font-black text-gray-900">Controle Financeiro</h2>
              <div className="grid grid-cols-2 gap-4">
                <Card className="text-center bg-green-50 border-green-200">
                  <div className="text-xs text-gray-400 mb-1">RECEITA TOTAL</div>
                  <div className="text-3xl font-black text-green-600">R$ {totalReceita.toFixed(2)}</div>
                </Card>
                <Card className="text-center bg-blue-50 border-blue-200">
                  <div className="text-xs text-gray-400 mb-1">PAGAMENTOS REGISTRADOS</div>
                  <div className="text-3xl font-black text-blue-600">{pagamentos.length}</div>
                </Card>
              </div>
              <Card>
                {pagamentos.length===0?(
                  <div className="text-center text-gray-400 py-8">Nenhum pagamento ainda.<br/><span className="text-sm">Use "Gerenciar" em um usuário para registrar pagamentos.</span></div>
                ):(
                  <table className="w-full text-sm">
                    <thead><tr className="text-xs text-gray-400 border-b">
                      <th className="text-left py-2">Data</th><th className="text-left py-2">Usuário</th>
                      <th className="text-left py-2">Valor</th><th className="text-left py-2">Método</th><th className="text-left py-2">Observação</th>
                    </tr></thead>
                    <tbody>{pagamentos.map(p=>(
                      <tr key={p.id} className="border-b border-gray-50 hover:bg-gray-50">
                        <td className="py-2 text-gray-400">{new Date(p.created_at).toLocaleDateString("pt-BR")}</td>
                        <td><div className="font-medium">{p.profiles?.full_name||"—"}</div><div className="text-xs text-gray-400">{p.profiles?.email}</div></td>
                        <td className="font-bold text-green-600">R$ {(p.valor||0).toFixed(2)}</td>
                        <td>{p.metodo}</td>
                        <td className="text-gray-500">{p.obs||"—"}</td>
                      </tr>
                    ))}</tbody>
                  </table>
                )}
              </Card>
            </>
          )}
          {tab==="Configurações"&&<ConfiguracoesSistema/>}
          {tab==="Tarifas"&&<ModuloTarifas/>}
          {tab==="Conversor"&&<ModuloConversor/>}
          {tab==="Reemissão"&&<ModuloReemissao/>}
          {tab==="Reemissão Manual"&&<ModuloReemissaoManual/>}
        </main>
      </div>
    </div>
  );
}

// ============================================================
// DASHBOARD USUÁRIO — sem WhatsApp flutuante, com modal PIX
// ============================================================
function Dashboard({ user, onLogout, onGoAdmin }) {
  const [modulo, setModulo] = useState("Tarifas");
  const [showPix, setShowPix] = useState(false);
  const isAdmin = user.email && user.email.toLowerCase() === ADMIN_EMAIL;
  const isTrial = user.plan === "trial";
  const isPendingPro = user.plan === "pending_pro";
  const trialDaysLeft = user.trialDays || 5;
  const menus = ["Tarifas", "Conversor", "Reemissão", "Reemissão Manual"];

  return (
    <div className="min-h-screen bg-gray-50">
      {showPix && <ModalPix onClose={() => setShowPix(false)} userName={user.name} />}

      <header className="bg-slate-900 text-white px-6 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <span className="text-lg font-black">⚡ Calcula Fácil</span>
          <span className="text-xs text-slate-400">Sistema Facilitador de Processos</span>
        </div>
        <div className="flex items-center gap-4">
          {isTrial && (
            <div className="bg-yellow-500/20 border border-yellow-400/40 rounded-lg px-3 py-1 text-yellow-300 text-xs font-semibold">
              ⏳ Trial: {trialDaysLeft} dias restantes
            </div>
          )}
          {isPendingPro && (
            <div className="bg-blue-500/20 border border-blue-400/40 rounded-lg px-3 py-1 text-blue-300 text-xs font-semibold">
              ⏳ Pagamento em análise
            </div>
          )}
          <span className="text-sm text-slate-300">● {user.name}</span>
          <Button variant="ghost" onClick={onLogout} className="text-white hover:bg-white/10 text-xs">Sair</Button>
        </div>
      </header>

      <div className="flex">
        <aside className="w-48 bg-white border-r border-gray-100 min-h-[calc(100vh-52px)] p-4">
          {menus.map(m => (
            <button key={m} onClick={() => setModulo(m)}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium mb-1 transition-all ${modulo===m?"bg-blue-600 text-white":"text-gray-600 hover:bg-gray-100"}`}>
              {m==="Tarifas"&&"🧮 "}{m==="Conversor"&&"✈️ "}{m==="Reemissão"&&"🔄 "}{m==="Reemissão Manual"&&"🔁 "}{m}
            </button>
          ))}

          {isAdmin && (
            <div className="mt-4 border-t border-gray-100 pt-4">
              <button onClick={onGoAdmin}
                className="w-full text-left px-3 py-2 rounded-lg text-sm font-bold mb-1 transition-all bg-purple-50 text-purple-700 hover:bg-purple-100 flex items-center gap-2">
                🔐 Painel Admin
              </button>
            </div>
          )}

          {(isTrial || isPendingPro) && (
            <div className="mt-6 bg-blue-50 border border-blue-200 rounded-xl p-3 text-xs text-blue-700">
              {isPendingPro ? (
                <>
                  <div className="font-bold mb-1">⏳ Em análise</div>
                  <div>Confirmaremos em até 24h.</div>
                </>
              ) : (
                <>
                  <div className="font-bold mb-1">Gostando? 🚀</div>
                  <div className="mb-2">Assine por R$ 49,99/mês</div>
                  <button onClick={() => setShowPix(true)}
                    className="block w-full py-1.5 bg-blue-600 text-white rounded-lg font-semibold hover:bg-blue-700 transition-all text-center">
                    ⭐ Assinar agora
                  </button>
                </>
              )}
            </div>
          )}
        </aside>

        <main className="flex-1 p-6">
          {modulo==="Tarifas"&&<ModuloTarifas/>}
          {modulo==="Conversor"&&<ModuloConversor/>}
          {modulo==="Reemissão"&&<ModuloReemissao/>}
          {modulo==="Reemissão Manual"&&<ModuloReemissaoManual/>}
        </main>
      </div>
    </div>
  );
}

// ============================================================
// APP ROOT
// ============================================================
export default function App() {
  const [screen, setScreen] = useState("loading");
  const [user, setUser] = useState(null);

  useEffect(() => {
    supabase.auth.getSession().then(async ({ data: { session } }) => {
      if (session) {
        const { data: profile } = await supabase.from("profiles").select("*").eq("id", session.user.id).single();
        let trialDaysLeft = 0;
        if (profile?.plan === "trial" && profile?.trial_start) {
          const diff = (new Date() - new Date(profile.trial_start)) / (1000*60*60*24);
          trialDaysLeft = Math.max(0, 5 - Math.floor(diff));
        }
        const userData = {
          id: session.user.id,
          name: profile?.full_name || session.user.email.split("@")[0],
          email: session.user.email,
          role: profile?.role || "user",
          plan: profile?.plan || "trial",
          trialDays: trialDaysLeft,
          company: profile?.company,
          seats: profile?.seats || 1,
        };
        setUser(userData);
        setScreen(userData.role === "admin" ? "admin" : "app");
      } else {
        setScreen("landing");
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (!session) { setUser(null); setScreen("landing"); }
    });
    return () => subscription.unsubscribe();
  }, []);

  const handleAuth = (userData) => {
    if (userData.blocked) { alert("Acesso bloqueado. Entre em contato com o suporte."); return; }
    setUser(userData);
    if (userData.role === "admin") setScreen("admin");
    else setScreen("app");
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setScreen("landing");
  };

  if (screen === "loading") return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center">
      <div className="text-white text-center">
        <div className="text-4xl mb-4">⚡</div>
        <div className="text-xl font-black">Calcula Fácil</div>
        <div className="text-slate-400 text-sm mt-2">Carregando...</div>
      </div>
    </div>
  );

  if (screen === "landing") return <LandingPage onLogin={() => setScreen("login")} onRegister={() => setScreen("register")} />;
  if (screen === "login") return <AuthPage mode="login" onAuth={handleAuth} onSwitch={() => setScreen("register")} onBack={() => setScreen("landing")} />;
  if (screen === "register") return <AuthPage mode="register" onAuth={handleAuth} onSwitch={() => setScreen("login")} onBack={() => setScreen("landing")} />;
  if (screen === "admin") return <PainelAdmin onLogout={handleLogout} />;
  if (screen === "app") return <Dashboard user={user} onLogout={handleLogout} onGoAdmin={() => setScreen("admin")} />;
}
